package rv.batch.format;import java.util.Locale;public class NumberFormat {protected final Locale locale;protected final String style;protected int min=0,max=3;protected NumberFormat(Locale l,String s){locale=l;style=s;}public static NumberFormat getNumberInstance(){return new DecimalFormat(Locale.getDefault(),"decimal");}public static NumberFormat getPercentInstance(Locale l){return new DecimalFormat(l,"percent");}public void setMaximumFractionDigits(int n){max=n;}public void setMinimumFractionDigits(int n){min=n;}public String format(long n){return format((double)n);}public String format(double n){return (String)rv.batch.Platform.invoke("format.number",n,locale.toLanguageTag(),style,min,max);}}
